var SPK='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9z"/><path d="M16 9a4 4 0 010 6M18.5 6.5a8 8 0 010 11"/></svg>';

/* ---------- voz ---------- */
var TOK=0,AE=null,LOADING={},VOICES=[];
var TAG={es:"es-MX",en:"en-US",de:"de-DE",pt:"pt-BR",fr:"fr-FR",zh:"zh-CN"};
var LOC={es:["es-MX","es-US","es-ES"],en:["en-US","en-GB"],de:["de-DE"],pt:["pt-BR","pt-PT"],fr:["fr-FR","fr-CA"],zh:["zh-CN","zh-TW","zh-HK"]};
var PR={es:["Trafisegur\u00edn","Trafisegur\u00edn"],en:["Trafisegur\u00edn","Trafisegureen"],de:["Trafisegur\u00edn","Trafisegurien"],pt:["Trafisegur\u00edn","Trafisegur\u00edm"],fr:["Trafisegur\u00edn","Trafiss\u00e9gurin"],zh:["Trafisegur\u00edn","\u7279\u62c9\u83f2\u585e\u53e4\u6797"]};
var MALE=/\b(juan|jorge|diego|carlos|markus|thomas|aaron|felipe|daniel|reed|eddy|rocko|alex|yunyang|male)\b/i,QUAL=/premium|enhanced|mejorada|增强|优化|erweitert|aprimorada|am[eé]lior[eé]e|natural|neural|siri/i;
var NOVEL=/^(albert|bad news|bahh|bells|boing|bubbles|cellos|deranged|good news|hysterical|jester|organ|superstar|trinoids|whisper|wobble|zarvox|fred|ralph|junior|kathy|princess)\b/i;
function loadVoices(){try{VOICES=window.speechSynthesis?(speechSynthesis.getVoices()||[]):[];}catch(e){VOICES=[];}}
loadVoices();try{if(window.speechSynthesis)speechSynthesis.addEventListener("voiceschanged",loadVoices);}catch(e){}
function langVoices(){var lc=LANG;return VOICES.filter(function(v){return v.lang&&v.lang.toLowerCase().replace("_","-").indexOf(lc)===0&&!NOVEL.test(v.name);});}
function score(v){var l=LOC[LANG]||[],i=l.indexOf(v.lang.replace("_","-"));return (i<0?0:10-i*2)+(QUAL.test(v.name)?6:0)+(MALE.test(v.name)?3:0)+(v.localService?1:0);}
function pickVoice(){var all=langVoices(),sv=LS.get(P+":sgvn","");if(sv){var f=all.filter(function(v){return v.name===sv;})[0];if(f)return f;}return all.sort(function(a,b){return score(b)-score(a);})[0]||null;}
var voiceOn=function(){return LS.get(P+":sgv",0)===1;};
var hasAud=function(id){return (AM[LANG]||[]).indexOf(id)>=0;};
function loadAud(cb){var l=LANG;if(window.SGA&&SGA[l]){cb(true);return;}if(LOADING[l]){LOADING[l].push(cb);return;}LOADING[l]=[cb];var s=document.createElement("script");s.src="sgaudio-"+l+".js";var fin=function(ok){var q=LOADING[l]||[];delete LOADING[l];q.forEach(function(f){f(ok);});};s.onload=function(){fin(!!(window.SGA&&SGA[l]));};s.onerror=function(){fin(false);};document.head.appendChild(s);}
function talk(on){if(LOW())return;document.body.classList.toggle("sg-talk",!!on);}
function stop(){TOK++;try{if(AE){AE.pause();}}catch(e){}try{if(window.speechSynthesis)speechSynthesis.cancel();}catch(e){}talk(false);}
function dev(text,tok,done){
 if(!window.speechSynthesis){done();return;}
 var v=pickVoice(),pr=PR[LANG]||PR.es,t=text.replace(/[·—–]/g,",").split(pr[0]).join(pr[1]),parts=t.match(/[^.!?…]+[.!?…]*/g)||[t],i=0;
 var next=function(){if(tok!==TOK)return;if(i>=parts.length){done();return;}
  var s=parts[i++].trim();if(!s){next();return;}
  var u=new SpeechSynthesisUtterance(s);if(v){u.voice=v;u.lang=v.lang;}else u.lang=TAG[LANG];
  u.rate=.96;u.pitch=1+(/\?/.test(s)?.06:0)+(/!/.test(s)?.05:0);
  u.onstart=function(){if(tok===TOK)talk(true);};u.onend=next;u.onerror=next;
  try{speechSynthesis.speak(u);}catch(e){done();}};
 next();}
function one(id,text,tok,done){
 if(id&&hasAud(id)){loadAud(function(ok){if(tok!==TOK)return;var src=ok&&window.SGA&&SGA[LANG]&&SGA[LANG][id];if(!src){dev(text,tok,done);return;}
   try{if(!AE)AE=new Audio();AE.onplay=function(){if(tok===TOK)talk(true);};AE.onended=function(){if(tok===TOK){talk(false);done();}};AE.onerror=function(){if(tok===TOK){talk(false);dev(text,tok,done);}};AE.src=src;var p=AE.play();if(p&&p.catch)p.catch(function(){talk(false);if(tok===TOK)dev(text,tok,done);});}catch(e){dev(text,tok,done);}});}
 else dev(text,tok,done);}
function sayList(list,force){if(!force&&!voiceOn())return;stop();var tok=TOK,i=0;
 try{if(!AE)AE=new Audio();}catch(e){}
 var step=function(){if(tok!==TOK)return;if(i>=list.length){talk(false);return;}var it=list[i++];one(it[0],it[1],tok,step);};step();}

/* ---------- datos del día ---------- */
function getSt(){var s=U.get("sg",null)||{},t=ymd(new Date());if(s.d!==t)s={d:t,a:[],done:0,streak:s.streak||0,last:s.last||"",best:s.best||0};return s;}
var setSt=function(s){U.set("sg",s);};
function dailyQ(){var b=dayIdx()*3,n=QS().length;return [0,1,2].map(function(i){return (b+i)%n;});}
function streakNow(st){var y=new Date();y.setDate(y.getDate()-1);return st.last===ymd(new Date())||st.last===ymd(y)?(st.streak||0):0;}
function cur(st){return SG.prac?{list:SG.prac.q,ans:SG.prac.a}:{list:dailyQ(),ans:st.a};}

/* ---------- sección ---------- */
function okLine(n){return [ "ok"+(n%3),L().ok[n%3] ];}
function noLine(n){return [ "no"+(n%2),L().no[n%2] ];}
function quizCard(st){
 var u=UI(),c=cur(st),n=c.ans.length;
 if(SG.fb===null&&n>=3){
  var good=c.list.reduce(function(a,q,i){return a+(c.ans[i]===QS()[q].c?1:0);},0),sk=streakNow(st);
  return '<div class="card"><h2 class="sh">'+(SG.prac?esc(u.prac):esc(u.done))+'</h2><p style="font-size:17px;font-weight:700;margin:4px 0">'+F(u.today,{a:good,t:3})+'</p>'
   +(sk?'<span class="tg" style="font-size:12px">'+esc(u.streak)+': '+sk+' '+(sk===1?u.d1:u.dn)+'</span>':'')
   +'<p class="mu" style="margin:8px 0 12px;font-size:14px">'+esc(u.back)+'</p>'
   +'<button type="button" class="btn pri" style="width:100%" data-sg="prac">'+esc(u.prac)+'</button>'
   +(SG.prac?'<button type="button" class="btn txt" style="width:100%;margin-top:6px" data-sg="exit">'+esc(u.done)+'</button>':'')+'</div>';}
 var idx=SG.fb!==null?n-1:n,qi=c.list[idx],q=QS()[qi],fb=SG.fb,html='<div class="card"><h2 class="sh">'+esc(SG.prac?u.prac:u.quiz)+'<em>'+F(u.qn,{n:idx+1,t:3})+'</em></h2><p class="sgq">'+esc(q.q)+'</p>';
 q.o.forEach(function(o,i){var cl="sgo";if(fb!==null){if(i===q.c)cl+=" ok";else if(i===fb)cl+=" bad";}
  html+='<button type="button" class="'+cl+'" data-sg="a:'+i+'"'+(fb!==null?' disabled':'')+'>'+esc(o)+'</button>';});
 if(fb!==null){var good=fb===q.c;html+='<div class="sgfb"><b>'+esc(good?u.right:u.wrong)+'</b><p>'+esc(good?q.e:u.ans+" "+q.o[q.c]+". "+q.e)+'</p><button type="button" class="btn pri" style="width:100%;margin-top:10px" data-sg="next">'+esc(n>=3?u.finish:u.next)+'</button></div>';}
 return html+'</div>';}
function viewSeg(){
 sprite();var u=UI(),st=getSt(),sk=streakNow(st),ph=PH(),pi=dayIdx()%ph.length;
 var h='<div class="card sgh"><div class="sgav-w">'+av(104,true)+'</div><div class="sgb"><div class="sgbub"><b>'+esc(u.hello)+'</b><span>'+esc(u.hello2)+'</span></div><div class="row" style="margin-top:10px;gap:8px"><button type="button" class="btn sgsp" data-sg="hi" aria-label="'+esc(u.say)+'">'+SPK+'<span>'+esc(u.say)+'</span></button>'
  +(sk?'<span class="tg" style="align-self:center;font-size:12px">'+esc(u.streak)+': '+sk+' '+(sk===1?u.d1:u.dn)+'</span>':'')+'</div></div></div>';
 h+='<div class="card"><h2 class="sh">'+esc(u.sc)+'<em>'+scList().length+'</em></h2><p class="mu" style="font-size:13px;margin:0 0 8px">'+esc(u.scs)+'</p>'+scList().map(function(s,k){return '<button type="button" class="sgsc-b" data-sg="sc:'+k+'"><i style="background:'+BGC[k%BGC.length]+'"></i><span>'+esc(s[0])+'</span><em>▶</em></button>';}).join('')+'</div>';
 h+='<div class="card"><h2 class="sh">'+esc(u.day)+'</h2><p class="sgq" style="margin:4px 0 10px">'+esc(ph[pi])+'</p><button type="button" class="btn sgsp" data-sg="p:'+pi+'">'+SPK+'<span>'+esc(u.say)+'</span></button></div>';
 h+=quizCard(st);
 var vs=langVoices(),cv=LS.get(P+":sgvn","");
 h+='<div class="card"><h2 class="sh">'+esc(u.voice)+'</h2><p class="mu" style="font-size:13px;margin:0 0 10px">'+esc(u.hint)+'</p>'
  +'<button type="button" class="btn '+(voiceOn()?"pri":"")+'" style="width:100%" data-sg="vtog">'+esc(voiceOn()?u.von:u.voff)+'</button>'
  +(vs.length?'<label class="lb" style="margin-top:12px" for="sgvs">'+esc(u.vdev)+'</label><select id="sgvs" data-sgsel="1" style="width:100%"><option value="">'+esc(u.vauto)+'</option>'+vs.map(function(v){return '<option value="'+esc(v.name)+'"'+(v.name===cv?' selected':'')+'>'+esc(v.name+" ("+v.lang+")")+'</option>';}).join("")+'</select>':'')
  +'<button type="button" class="btn" style="width:100%;margin-top:10px" data-sg="vtest">'+esc(u.vtest)+'</button></div>';
 h+='<div class="card"><h2 class="sh">'+esc(u.phr)+'<em>'+ph.length+'</em></h2>'+ph.map(function(t,i){return '<div class="sgp"><span>'+esc(t)+'</span><button type="button" class="btn sgsp" data-sg="p:'+i+'" aria-label="'+esc(u.say)+'">'+SPK+'</button></div>';}).join("")+'</div>';
 return h;}

/* ---------- Intro ---------- */
function sgIntro(){
 sprite();var u=UI(),ph=PH();SG.ip=Math.floor(Math.random()*ph.length);SG.iq=Math.floor(Math.random()*QS().length);
 setTimeout(stage1,350);setTimeout(stage2,4200);
 return '<div class="sgi"><div class="sgi-av">'+av(66,true)+'</div><div class="sgi-b" id="sgib"><b>'+esc(u.hello)+'</b><span>'+esc(ph[SG.ip])+'</span><button type="button" class="sgi-sp" data-sg="isay" aria-label="'+esc(u.say)+'">'+SPK+'</button></div></div>';}
function stage1(){if(!document.getElementById("sgib"))return;sayList([["hi",L().hi],["p"+SG.ip,PH()[SG.ip]]],false);}
function stage2(){var b=document.getElementById("sgib");if(!b||b.dataset.done)return;var q=QS()[SG.iq],u=UI();
 b.innerHTML='<b>'+esc(u.qi)+'</b><span>'+esc(q.q)+'</span><div class="sgi-o">'+q.o.map(function(o,i){return '<button type="button" data-sg="iq:'+i+'">'+esc(o)+'</button>';}).join("")+'</div>';
 sayList([["q"+SG.iq,q.q]],false);}
function introAns(i){var b=document.getElementById("sgib");if(!b||b.dataset.done)return;b.dataset.done="1";var q=QS()[SG.iq],u=UI(),good=i===q.c,ln=good?okLine(SG.iq):noLine(SG.iq);
 b.innerHTML='<b>'+esc(good?u.right:u.wrong)+'</b><span>'+esc(ln[1]+(good?"":" "+u.ans+" "+q.o[q.c]+"."))+'</span>';
 try{clearTimeout(L3DTM);L3DTM=setTimeout(l3dClose,4200);var p=document.querySelector("#l3dsp .l3p");if(p)p.style.display="none";}catch(e){}
 sayList([[ln[0],ln[1]]],false);}

/* ---------- eventos ---------- */
function reR(){try{render();}catch(e){}}
document.addEventListener("click",function(e){var b=e.target.closest("[data-sg]");if(!b)return;var a=b.dataset.sg,st;
 if(a.indexOf("a:")===0){st=getSt();var c=cur(st),n=c.ans.length;if(SG.fb!==null||n>=3)return;var i=+a.slice(2),qi=c.list[n],q=QS()[qi];c.ans.push(i);if(!SG.prac)setSt(st);SG.fb=i;
  var ln=i===q.c?okLine(n):noLine(n);reR();sayList([[ln[0],ln[1]],["e"+qi,q.e]],false);}
 else if(a==="next"){st=getSt();var c2=cur(st);SG.fb=null;if(!SG.prac&&c2.ans.length>=3&&!st.done){var y=new Date();y.setDate(y.getDate()-1);st.streak=st.last===ymd(y)?(st.streak||0)+1:1;st.last=ymd(new Date());st.best=Math.max(st.best||0,st.streak);st.done=1;setSt(st);}
  stop();reR();if(c2.ans.length>=3){var good=c2.list.reduce(function(s,q,i){return s+(c2.ans[i]===QS()[q].c?1:0);},0);sayList([good===3?["dall",L().dall]:["dpart",L().dpart]],false);}window.scrollTo(0,0);}
 else if(a==="prac"){var pool=QS().map(function(_,i){return i;}).sort(function(){return Math.random()-.5;});SG.prac={q:pool.slice(0,3),a:[]};SG.fb=null;stop();reR();}
 else if(a==="exit"){SG.prac=null;SG.fb=null;reR();}
 else if(a==="vtog"){LS.set(P+":sgv",voiceOn()?0:1);if(voiceOn())sayList([["hi",L().hi]],true);else stop();reR();}
 else if(a==="vtest"||a==="hi"){sayList([["hi",L().hi]],true);}
 else if(a.indexOf("p:")===0){var k=+a.slice(2);sayList([["p"+k,PH()[k]]],true);}
 else if(a==="isay"){e.stopPropagation();sayList([["hi",L().hi],["p"+SG.ip,PH()[SG.ip]]],true);}
 else if(a.indexOf("iq:")===0){e.stopPropagation();introAns(+a.slice(3));}});
document.addEventListener("change",function(e){var s=e.target.closest("[data-sgsel]");if(!s)return;LS.set(P+":sgvn",s.value);sayList([["hi",L().hi]],true);});



